//! Provider logos (icons/providers): the SVG for a provider
//! id, recoloured to the theme's text colour and handed to QML as a data
//! URL. (The files are single-colour artwork in black.)

// Rust guideline compliant 2026-10-09

// `LOGOS`: (id, SVG text), sorted by id (generated by build.rs).
include!(concat!(env!("OUT_DIR"), "/provider_logos.rs"));

/// Ids that share another's logo.
fn alias(id: &str) -> &str {
    match id {
        "openai-codex" | "codex" | "chatgpt" | "azure-openai" => "openai",
        "claude" | "claude-bridge" => "anthropic",
        "gemini" | "google-gemini-cli" | "google-vertex" | "vertex" => "google",
        "copilot" => "github-copilot",
        "ollama-cloud" => "ollama",
        "deepseek-anthropic" => "deepseek",
        // (Coding plans for Claude Code show their maker's.)
        "minimax" | "minimax-anthropic" | "minimax-plan" => "minimax-coding-plan",
        "zai" | "glm-coding" => "zai-coding-plan",
        "moonshot" | "kimi" | "kimi-code" => "kimi-for-coding",
        "grok" => "xai",
        "opencode-go" | "opencode-zen" => "opencode",
        "llamacpp" | "llama-cpp" => "llama.cpp",
        other => other,
    }
}

/// Who made a model (`provider/model`), as a logo id: by the model's name
/// (Claude through OpenCode is Anthropic's, GLM on a coding plan Z.ai's),
/// else by its provider (a local server's own logo); None when unknown.
pub fn maker_of(model: &str) -> Option<&'static str> {
    let (provider, id) = model.split_once('/').unwrap_or(("", model));
    let id = id.to_lowercase();
    let has = |words: &[&str]| words.iter().any(|w| id.contains(w));
    // (OpenAI's o-series: o3, o4-mini…; its open models, gpt-oss.)
    let o_series = id.rsplit('/').next().is_some_and(|n| n.len() > 1 && n.starts_with('o') && n[1..].starts_with(|c: char| c.is_ascii_digit()));
    let by_name = match () {
        () if has(&["claude", "opus", "sonnet", "haiku", "fable"]) => Some("anthropic"),
        () if has(&["gpt", "codex"]) || o_series => Some("openai"),
        () if has(&["glm"]) => Some("zai-coding-plan"),
        () if has(&["kimi", "moonshot"]) => Some("kimi-for-coding"),
        () if has(&["deepseek"]) => Some("deepseek"),
        () if has(&["gemini", "gemma"]) => Some("google"),
        () if has(&["grok"]) => Some("xai"),
        () if has(&["minimax"]) => Some("minimax-coding-plan"),
        () if has(&["mistral", "codestral", "devstral", "magistral"]) => Some("mistral"),
        () => None,
    };
    by_name.and_then(id_for).or_else(|| id_for(provider).filter(|_| !provider.is_empty()))
}

/// The logo id for a provider ("openai-codex", "anthropic/…"), if any.
pub fn id_for(provider: &str) -> Option<&'static str> {
    let p = provider.to_lowercase();
    let first = p.split(['/', ':']).next().unwrap_or("");
    let want = alias(first);
    LOGOS.iter().find(|(id, _)| *id == want).map(|(id, _)| *id)
}

/// `data:image/svg+xml;base64,…` of the provider's logo in `color`
/// (`#rrggbb`), or "" when it has none.
pub fn data_url(provider: &str, color: &str) -> String {
    let Some(id) = id_for(provider) else { return String::new() };
    let svg = LOGOS.iter().find(|(i, _)| *i == id).map_or("", |(_, s)| *s);
    let color = if color.starts_with('#') && color.len() <= 9 { color } else { "#888888" };
    // Unfilled shapes inherit the root's fill (given one unless it has its
    // own: twice is invalid, and the logo isn't drawn); explicit dark fills
    // follow it.
    let root_fill = svg.split_once('>').is_some_and(|(tag, _)| tag.contains(" fill="));
    let recoloured = if root_fill { svg.to_owned() } else { svg.replacen("<svg ", &format!("<svg fill=\"{color}\" "), 1) };
    let recoloured = recoloured
        .replace("fill=\"black\"", &format!("fill=\"{color}\""))
        .replace("fill=\"#000\"", &format!("fill=\"{color}\""))
        .replace("fill=\"#000000\"", &format!("fill=\"{color}\""))
        .replace("fill=\"currentColor\"", &format!("fill=\"{color}\""));
    format!("data:image/svg+xml;base64,{}", base64(recoloured.as_bytes()))
}

fn base64(bytes: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let n = u32::from(chunk[0]) << 16 | u32::from(*chunk.get(1).unwrap_or(&0)) << 8 | u32::from(*chunk.get(2).unwrap_or(&0));
        for i in 0..4 {
            if i <= chunk.len() {
                out.push(T[(n >> (18 - 6 * i) & 63) as usize] as char);
            } else {
                out.push('=');
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn maps_providers_to_logos() {
        assert_eq!(id_for("openai-codex"), Some("openai"));
        assert_eq!(id_for("anthropic/claude-sonnet"), Some("anthropic"));
        assert_eq!(id_for("Gemini"), Some("google"));
        assert_eq!(id_for("llama.cpp"), Some("llama.cpp"));
        assert_eq!(id_for("llamacpp/Qwen3-4B"), Some("llama.cpp"));
        assert_eq!(id_for("vllm"), Some("vllm"));
        assert_eq!(id_for("koboldcpp"), None);
        // Harlo's cloud providers.
        for (id, logo) in [("xai", "xai"), ("deepseek-anthropic", "deepseek"), ("minimax-anthropic", "minimax-coding-plan"), ("zai", "zai-coding-plan"), ("moonshot", "kimi-for-coding"), ("gemini", "google"), ("fireworks", "fireworks"), ("glm-coding", "zai-coding-plan"), ("kimi-code", "kimi-for-coding"), ("minimax-plan", "minimax-coding-plan"), ("opencode-go", "opencode")] {
            assert_eq!(id_for(id), Some(logo), "{id}");
        }
        // A model's maker: by its name, whoever serves it.
        for (model, maker) in [("opencode-go/claude-haiku-5-5", Some("anthropic")), ("glm-coding/glm-5.3[1m]", Some("zai-coding-plan")), ("codex/gpt-6.1-sol", Some("openai")),
                               ("openai/o4-mini", Some("openai")), ("groq/openai/gpt-oss-120b", Some("openai")), ("together/deepseek-ai/DeepSeek-V4.1-Flash", Some("deepseek")),
                               ("gemini/gemini-4-carbon", Some("google")), ("llamacpp/Qwen3-4B", Some("llama.cpp")), ("anthropic/claude-sonnet-5-5", Some("anthropic")),
                               ("kimi-code/k3.1-pro", Some("kimi-for-coding")), ("opencode-go/hy4", Some("opencode")), ("koboldcpp/x", None), ("", None)] {
            assert_eq!(maker_of(model), maker, "{model}");
        }
        assert_eq!(base64(b"Man"), "TWFu");
        assert_eq!(base64(b"Ma"), "TWE=");
        assert_eq!(base64(b"M"), "TQ==");
        let url = data_url("openai-codex", "#e0e0e0");
        assert!(url.starts_with("data:image/svg+xml;base64,"));
        assert_eq!(data_url("koboldcpp", "#fff"), "");
    }

    /// Every logo, recoloured, is still valid: its `<svg>` tag has no
    /// attribute twice (Qt draws nothing then), and it takes the colour.
    #[test]
    fn recoloured_logos_stay_valid() {
        for (id, svg) in LOGOS {
            let mut out = svg.to_string();
            for dark in ["black", "#000", "#000000", "currentColor"] {
                out = out.replace(&format!("fill=\"{dark}\""), "fill=\"#123456\"");
            }
            let root_fill = svg.split_once('>').is_some_and(|(tag, _)| tag.contains(" fill="));
            if !root_fill {
                out = out.replacen("<svg ", "<svg fill=\"#123456\" ", 1);
            }
            let tag = out.split_once('>').map(|(t, _)| t.to_owned()).unwrap_or_default();
            let names: Vec<&str> = tag.split_whitespace().skip(1).filter_map(|a| a.split_once('=').map(|(n, _)| n)).collect();
            let mut seen = std::collections::HashSet::new();
            for n in &names {
                assert!(seen.insert(*n), "{id}: {n} twice in {tag}");
            }
            // (The real function, too.)
            let url = data_url(id, "#123456");
            assert!(url.starts_with("data:image/svg+xml;base64,"), "{id}");
        }
    }
}
